from html.parser import HTMLParser
from pathlib import Path
class Page(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tags = []
    def handle_starttag(self, tag, attrs):
        self.tags.append([tag, dict(attrs), ''])
    def handle_data(self, text):
        if self.tags:
            self.tags[-1][2] += text
page = Page()
page.feed(Path('index.html').read_text())
assert any(tag == 'h1' and text.strip() == 'Sign up' for tag, attrs, text in page.tags)
assert any(tag == 'form' for tag, attrs, text in page.tags)
ids = {attrs.get('id') for tag, attrs, _ in page.tags if tag == 'input' and attrs.get('type') == 'email'} - {None, ''}
assert any(tag == 'label' and attrs.get('for') in ids and text.strip() == 'Email' for tag, attrs, text in page.tags)
assert any(tag == 'button' and attrs.get('type') == 'submit' and text.strip() for tag, attrs, text in page.tags)

