def read_record(record):
    name = record['display_name'] if 'display_name' in record else record['name']
    return {'id': record['id'], 'display_name': name}

check:
from app import read_record
assert read_record({'id': 1, 'name': 'old'}) == {'id': 1, 'display_name': 'old'}
assert read_record({'id': 2, 'display_name': 'new'}) == {'id': 2, 'display_name': 'new'}
assert read_record({'id': 3, 'name': 'old', 'display_name': 'new'}) == {'id': 3, 'display_name': 'new'}
